from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
w=json.loads((root/'data/world.json').read_text())
allies=json.loads((root/'data/first-recruits.json').read_text())['characters']
common='''Original BELDE: THE WRONG COMMANDER visual-preproduction concept art, a beautiful handcrafted PIXEL ART warm dark fairytale tower-defense RPG. Hard deliberate pixel clusters, rich material detail, dark navy outlines, muted moss and teal, warm parchment and worn copper highlights, upper-left lighting. Three-quarter top-down battlefield camera, legible silhouette and clear shapes. No photorealism, no glossy vector art, no existing commercial characters. Masterful composition and thoughtful negative space. These are original reference illustrations, not a working game screenshot. Wide landscape canvas. Short legible labels only. '''
briefs=[]
def add(id,title,description,prompt):briefs.append(dict(id=id,title=title,file=f'art/{id}.png',description=description,prompt=common+prompt))
for part,monsters in [('a',w['enemies'][:4]),('b',w['enemies'][4:8])]:
 rows=[]
 for i,e in enumerate(monsters,1):rows.append('ROW '+str(i)+': '+json.dumps(e,ensure_ascii=False))
 add('12-enemies-'+part,'The Invaders · '+part.upper(),'Four enemy models with movement, attack, two ability effects and surrender key poses; conceptual motion reference, not complete clips.',f'''A polished enemy visual reference contact sheet with EXACTLY FOUR rows and EIGHT columns. Columns: PORTRAIT, IDLE, WALK, RUN, BASIC ATTACK, ABILITY I, ABILITY II, SURRENDER. Label each row with its ID and name. Clearly distinct species. Every walking/running/attacking figure shows its entire body. Each ability illustration includes the actor and its own signature effect and floor telegraph. Surrender is calm: lower weapon, show open hands and small white cloth. Do not confuse surrender with lying dead. No gore. Show a small noncombatant traveling-with-luggage thumbnail near the portrait if space permits. Follow these exact designs:\n'''+ '\n'.join(rows))
boss=w['enemies'][-1]
add('13-avar ren'.replace(' ',''),'Avarren · The Uncrowned','Demon King model, attack/ability tells, vulnerable face, and two final-choice visual studies.',f'''Create one exquisite BOSS MODEL AND ATTACK-TELEGRAPH BOARD. Upper half: one large full body 3/4 view of AVARREN THE UNCROWNED, plus side/back costume studies and expressive portrait showing a vulnerable adult face. Lower half: six clear small panels IDLE, WALK/RUN, BASIC ATTACK, ABILITY I with ground danger tell then active effect, ABILITY II with tell then active effect, DISARMED/SURRENDER. Two small ending vignettes: FORGIVE shows crown held in open hands with rebuilding; REFUSE PARDON shows crown sealed in copper chest and king escorted to hearing. Never graphic execution. Keep boss face, antlers, cracked mantle and root-veins consistent. Actual design:\n{json.dumps(boss,ensure_ascii=False)}''')
for n,maps in [(1,w['maps'][:3]),(2,w['maps'][3:])]:
 add('14-maps-'+str(n),'Battlefields · '+('I–III' if n==1 else 'IV–VI'),'Three map environment studies with route and deployment overlays. Exact coordinates remain authoritative in world.json.',f'''A museum-quality PIXEL ART MAP DESIGN TRIPTYCH. Three side-by-side full map panels, all drawn same top-down three-quarter scale. Each panel contains a genuinely detailed and unique environment, clear entry and defended gate, branching ochre packed-earth ENEMY paths with small hollow red chevrons and separate cyan dashed double-rail ALLIED PATROL tracks on perimeter. Small parchment square tower pads. Dark nonwalkable scenery never obscures paths. Add a small bare route-plan inset in each panel, and name/ID at top. Preserve each map's landmark, mood, objectives, and distinct route pattern. These are designed battlefields, not generic landscape paintings. No large HUD overlays; emphasize play space. Maps:\n{json.dumps(maps,ensure_ascii=False)}''')
add('15-recruitment','Places Worth Fighting For','Five recruitment-location vignettes plus Tornel’s introduction-card layout.',f'''A polished recruitment environment-and-card concept board. Exactly FIVE location vignettes arranged across the left two-thirds: a friendly rough bar with six silhouettes; a sunlit royal training yard with fifteen knight candidates shown as a crowd, not individually counted; a repaired village square with ten resourceful candidates; a cosmopolitan capital mercenary market with ten candidates; a dignified prison visiting room with twelve adult recruits, warm light and no torture. Clear beautiful environmental storytelling and distinct architecture. Name the five places as specified. Right third: large readable recruitment card for TORNEL ASHHAND, DPS, AGE31, HP90, ATK16 / 0.8s, RANGE3. Card has head portrait and fullbody sprite: soot-dark skin,copper closecrop,red sleeveless coat,two hatchets. Two ability cards KILN SPLITTER (16s) shows triple hatchet line, ASHEN TEMPO(24s) shows orbiting ember ticks. Bottom choices 0/2 and RECRUIT. Small walk/run/attack thumbnails below portrait. Use original consistent pixelart UI, navy panels,parchment/copper edges. Location briefs:\n{json.dumps(w['recruitment_locations'],ensure_ascii=False)}''')
add('16-interface','A Connected Command','Static game HUD, compact extension, detached editor and session-warning layouts; no software implementation.',f'''A professional PIXEL ART GAME UI PRESENTATION BOARD. Four clearly separated panels: (1) large PC GAMEPLAY HUD over Hinge Gate battlefield with readable gate HP,wave,unit cards, healthbars, two cooldown wedges, guard/patrol/advance icons and selected range ring. (2) detached EDITOR window, left tower/unit/track/trap tools,centralmap,right properties, undo/redo toolbar,bottom history,cyan snapped ghost and separate red crosshatched invalid ghost labeled TRACK BLOCKED. (3) compact extension popup with connected-pair icon,map thumbnail,Undo,Redo,Open Full Editor, status SYNCED. (4) clean modal session-warning card with exact heading MULTIPLE GAME INSTANCES DETECTED and readable short body "One active PC game and one connected editor are permitted." Button "Disconnect other session to continue". Add small sync-status symbols: check Synced,clock Pending,split-diamond Conflict,broken-chain Disconnected. These are static art mockups, beautiful pixel borders plus clear typography, no source code or protocol text. UI design:\n{json.dumps(w['ui'],ensure_ascii=False)}''')
add('17-towers-traps-vfx','Tools of the Commander','Tower upgrades, traps, track pieces, deployment modes and class-shaped VFX studies.',f'''A clean highly detailed PIXEL ART ASSET DESIGN BOARD with four horizontal bands. Band1 FOUR tower families each three upgrade stages I II III, recognizably same base each time; show occupied ranged tower firing through slit and spread reticle. Band2 THREE traps each setup,armed,triggered,spent poses; show floor footprint. Band3 track editor KIT: straight,quarterturn,Tjunction,bridge,endpoint,waypoint,ramp,blockedcollision/hatchedghost; beside it Guard(circle)Patrol(doublearrow)Advance(spearhead) icons and unit poses. Band4 distinct role VFX strips: healer four-pip mint cross and upward threads; DPS copper triangular slash and impact; tanker blue square protection brackets; strategist amber HEXAGON trap glyph; enemy hollow red serrated warning with pale broken edge. Show windup,release,impact,decay in each strip. Effects are restrained and don't hide feet. Each tower & trap follows:\n{json.dumps(w['towers'],ensure_ascii=False)}\n{json.dumps(w['traps'],ensure_ascii=False)}''')
add('18-storyboard','Five Acts · A Crown Set Down','Five-act visual storyboard and both ending compositions with survivor/title-card treatment.',f'''A moving cinematic PIXEL ART STORYBOARD in seven panels, structured 3top/3middle/1widebottom. Panel1THE WRONG COMMANDER: confused new commander with wrong royal dispatch recruits two adults at gate. Panel2FRIENDS AND MONSTERS: wave of small monsters approaches,one lowers spear and raises white cloth,player notices. Panel3THE PRICE OF VICTORY: siege, split rescue enclosures, five distinct monster generals negotiate, two may join. Panel4THE CHOOSING: crossroads with capital market and prison door, surviving allies count visible by silhouettes, reinforcements arrive. Panel5THE LAST STAND: Avarren antlercrown cracked mantle overlooks dual-route courtyard; allies brace. Panel6FORGIVE: disarmed king, humans and monster allies rebuild with crown in openhands. Widebottom splits REFUSE PARDON (king escorted to public hearing,crown sealed,no gore) and EPILOGUE(titlecard with survivor portraits,empty place and a tool for fallen ally). Maintain visual continuity:copper dawn->blue ford->firelit siege->warm candles->rootglow->dawn. Add small 0–5 /5–11 /11–18 /18–24 /24–30min captions. Sensitivity and readable story acting, not generic battles. Story details:\n{json.dumps(w['storyboard'],ensure_ascii=False)}\nEndings:{json.dumps(w['endings'],ensure_ascii=False)}''')
tornel=allies[0]
add('19-tornel-motion','Tornel · Motion Study','Sequential pose studies for walking, running, basic attack and two abilities. Artistic keyframes still require cleanup and timing validation.',f'''A highly consistent PIXEL ART ANIMATION KEYFRAME STUDY of ONE character, TORNEL ASHHAND. Exactly FIVE horizontal rows; each row contains EIGHT evenly spaced fullbody poses on subtle 64x64 reference grids with locked footbaseline and consistent scale/costume/face/weapons. ROW1 WALK: leftcontact,down,passing,oppositecontact,down,passing,returncontact,hold. ROW2 RUN: leftcontact,compression,airborne,passing,rightcontact,compression,airborne,passing. ROW3 BASIC ATTACK: hatchet draw,torso windup,forwardrelease,hatchet airborne,followthrough,recovery,return,hold; flyinghatchet separate above row. ROW4 KILN SPLITTER: overhead windup,twohandbrace,forwardchop,release of line of three golden hatchets,followthrough,square sparks,return,hold. ROW5 ASHEN TEMPO: blades tap,embers ignite,lower shoulders,threeemberticks orbit grips,compact ready,breath,embers fade,return. NO alternating random character identities. Draw actual successive motion, not identical idle copies. Keep hatchetprop consistency and clearly moving legs. Header says KEYFRAME REFERENCE. Character:\n{json.dumps({k:tornel[k] for k in ['name','appearance','silhouette','weapon','palette','abilities']},ensure_ascii=False)}''')
(root/'art/world-image-briefs.json').write_text(json.dumps(briefs,indent=2,ensure_ascii=False))
print('Prepared',len(briefs),'world/animation/UI boards')
